const records = items.map((item) => item.json || {});
const now = new Date();
const since = new Date(now);
since.setDate(now.getDate() - 7);

const fieldNames = new Set(records.flatMap((record) => Object.keys(record)));
const required = ['Status', 'Business Name'];
const recommended = ['Date Emailed', 'Follow-up 1 Sent', 'Follow-up 2 Sent', 'Replied Date', 'Campaign ID', 'Copy Version', 'Quote Value', 'Quoted Gross Profit', 'Won Gross Profit'];
const missingRequired = required.filter((name) => !fieldNames.has(name));
const missingRecommended = recommended.filter((name) => !fieldNames.has(name));

function date(value) {
  if (!value) return null;
  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? null : parsed;
}
function inWeek(value) {
  const parsed = date(value);
  return Boolean(parsed && parsed >= since && parsed <= now);
}
function number(value) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
}
function status(record) {
  return String(record.Status || '').trim();
}

const counts = {
  totalRecords: records.length,
  emailFoundPending: 0,
  readyToEmail: 0,
  emailed: 0,
  followup1: 0,
  followup2: 0,
  replied: 0,
  quoteRequested: 0,
  won: 0,
  lost: 0,
  initialSentLast7Days: 0,
  followup1SentLast7Days: 0,
  followup2SentLast7Days: 0,
  repliesLast7Days: 0,
  quotedRevenue: 0,
  quotedGrossProfit: 0,
  wonGrossProfit: 0
};
const byCampaign = {};

for (const record of records) {
  const stage = status(record);
  if (stage === 'Email Found') counts.emailFoundPending += 1;
  if (stage === 'Ready to Email') counts.readyToEmail += 1;
  if (stage === 'Emailed') counts.emailed += 1;
  if (stage === 'Follow-up 1') counts.followup1 += 1;
  if (stage === 'Follow-up 2') counts.followup2 += 1;
  if (stage === 'Replied') counts.replied += 1;
  if (stage === 'Quote Requested' || stage === 'Quote Sent') counts.quoteRequested += 1;
  if (stage === 'Won') counts.won += 1;
  if (stage === 'Lost') counts.lost += 1;
  if (inWeek(record['Date Emailed'])) counts.initialSentLast7Days += 1;
  if (inWeek(record['Follow-up 1 Sent'])) counts.followup1SentLast7Days += 1;
  if (inWeek(record['Follow-up 2 Sent'])) counts.followup2SentLast7Days += 1;
  if (inWeek(record['Replied Date'])) counts.repliesLast7Days += 1;
  counts.quotedRevenue += number(record['Quote Value']);
  counts.quotedGrossProfit += number(record['Quoted Gross Profit']);
  counts.wonGrossProfit += number(record['Won Gross Profit']);

  const key = String(record['Campaign ID'] || 'unattributed');
  if (!byCampaign[key]) byCampaign[key] = { records: 0, ready: 0, replied: 0, quotedGP: 0, wonGP: 0 };
  byCampaign[key].records += 1;
  if (stage === 'Ready to Email') byCampaign[key].ready += 1;
  if (stage === 'Replied') byCampaign[key].replied += 1;
  byCampaign[key].quotedGP += number(record['Quoted Gross Profit']);
  byCampaign[key].wonGP += number(record['Won Gross Profit']);
}

const report = [
  'NOVAMERCH WEEKLY GROWTH REVIEW',
  `Generated: ${now.toLocaleString('en-AU', { timeZone: 'Australia/Sydney' })}`,
  '',
  `Lead records scanned: ${counts.totalRecords}`,
  `Email Found awaiting review: ${counts.emailFoundPending}`,
  `Approved Ready to Email: ${counts.readyToEmail}`,
  `Active sales stages — Emailed: ${counts.emailed}; Follow-up 1: ${counts.followup1}; Follow-up 2: ${counts.followup2}; Replied: ${counts.replied}; Quote requested/sent: ${counts.quoteRequested}; Won: ${counts.won}; Lost: ${counts.lost}`,
  '',
  'LAST 7 DAYS',
  `Initial sends recorded: ${counts.initialSentLast7Days}`,
  `Follow-up 1 recorded: ${counts.followup1SentLast7Days}`,
  `Follow-up 2 recorded: ${counts.followup2SentLast7Days}`,
  `Replies recorded: ${counts.repliesLast7Days}`,
  '',
  'PROFIT SIGNALS',
  `Quoted revenue recorded: A$${counts.quotedRevenue.toFixed(2)}`,
  `Quoted gross profit recorded: A$${counts.quotedGrossProfit.toFixed(2)}`,
  `Won gross profit recorded: A$${counts.wonGrossProfit.toFixed(2)}`,
  '',
  missingRequired.length ? `BLOCKER: Missing required fields: ${missingRequired.join(', ')}.` : 'Required lead fields detected.',
  missingRecommended.length ? `MEASUREMENT GAP: Add or map: ${missingRecommended.join(', ')}.` : 'Recommended funnel fields detected.',
  '',
  'NEXT REVIEW QUESTION',
  'Which source/segment/copy produced the most quoted and won gross profit, and what is the earliest weak funnel stage?'
].join('\n');

return [{ json: { report, counts, byCampaign, missingRequired, missingRecommended, generatedAt: now.toISOString() } }];
